import{_ as n,I as r,c as i,o as s,ag as t,J as o}from"./chunks/framework.Vyheyqg9.js";const b=JSON.parse('{"title":"AWS: from cloud foundations to application development","description":"","frontmatter":{},"headers":[],"relativePath":"aws/index.md","filePath":"aws/index.md"}'),d={name:"aws/index.md"};function l(c,e,p,h,u,m){const a=r("MermaidDiagram");return s(),i("div",null,[e[0]||(e[0]=t('<h1 id="aws-from-cloud-foundations-to-application-development" tabindex="-1">AWS: from cloud foundations to application development <a class="header-anchor" href="#aws-from-cloud-foundations-to-application-development" aria-label="Permalink to “AWS: from cloud foundations to application development”">​</a></h1><p>Understand where an application runs, how its parts communicate, and who can access them. Then connect AWS services into a system you can explain and troubleshoot. This path combines the supplied <strong>CloudX: AWS Practitioner for JS</strong> and <strong>CloudX Associate: AWS JavaScript Developer</strong> material, with additional beginner explanations and corrections to older examples.</p><p>No previous cloud experience is required. Familiarity with JavaScript, promises, npm, a terminal, HTTP and JSON will help with the development chapters. Start with the beginner guide if servers, DNS or networking are unfamiliar.</p><h2 id="reading-order" tabindex="-1"><span class="hub-section-number">1 </span>Reading order <a class="header-anchor" href="#reading-order" aria-label="Permalink to “1 Reading order”">​</a></h2><h3 id="cloud-foundations" tabindex="-1"><span class="hub-section-number">1.1 </span>Cloud foundations <a class="header-anchor" href="#cloud-foundations" aria-label="Permalink to “1.1 Cloud foundations”">​</a></h3><table tabindex="0"><thead><tr><th>Chapter</th><th>What it explains</th></tr></thead><tbody><tr><td><a href="./beginner-guide.html">Beginner guide</a></td><td>Servers, cloud models, networks, regions, responsibility, cost and reliability</td></tr><tr><td><a href="./account-and-tools.html">Account, tools and costs</a></td><td>Account setup, MFA, CLI profiles, SDK credentials, budgets and resource lifetime</td></tr><tr><td><a href="./iam-and-security.html">IAM and security</a></td><td>Identities, permissions, roles, policies, STS and least privilege</td></tr><tr><td><a href="./infrastructure-as-code.html">CDK and CloudFormation</a></td><td>Infrastructure definitions, stacks, deployment changes and resource ownership</td></tr></tbody></table><h3 id="application-services" tabindex="-1"><span class="hub-section-number">1.2 </span>Application services <a class="header-anchor" href="#application-services" aria-label="Permalink to “1.2 Application services”">​</a></h3><table tabindex="0"><thead><tr><th>Chapter</th><th>What it explains</th></tr></thead><tbody><tr><td><a href="./storage-and-frontend.html">S3 and CloudFront</a></td><td>Object storage, frontend hosting, caching, versioning and private origins</td></tr><tr><td><a href="./serverless-and-apis.html">Lambda and API Gateway</a></td><td>Request handling, execution environments, concurrency, packaging and API boundaries</td></tr><tr><td><a href="./databases.html">DynamoDB and RDS</a></td><td>Access patterns, indexes, transactions, SQL, connections and recovery</td></tr><tr><td><a href="./file-imports.html">S3 imports and events</a></td><td>Presigned uploads, validation, event processing and duplicate handling</td></tr><tr><td><a href="./messaging.html">SQS and SNS</a></td><td>Queues, fanout, ordering, retries, batch failures and dead-letter queues</td></tr><tr><td><a href="./authentication.html">Cognito and application access</a></td><td>Tokens, user pools, identity pools, API authorizers and resource ownership</td></tr></tbody></table><h3 id="infrastructure-and-operations" tabindex="-1"><span class="hub-section-number">1.3 </span>Infrastructure and operations <a class="header-anchor" href="#infrastructure-and-operations" aria-label="Permalink to “1.3 Infrastructure and operations”">​</a></h3><table tabindex="0"><thead><tr><th>Chapter</th><th>What it explains</th></tr></thead><tbody><tr><td><a href="./networking.html">VPC and networking</a></td><td>Subnets, routing, gateways, security groups, DNS and private connectivity</td></tr><tr><td><a href="./compute-and-scaling.html">EC2 and scaling</a></td><td>Virtual machines, storage, instance configuration, load balancing and availability</td></tr><tr><td><a href="./delivery-and-operations.html">Delivery and operations</a></td><td>CI/CD, observability, deployment recovery, cost review and cleanup</td></tr></tbody></table><h3 id="optional-depth-and-references" tabindex="-1"><span class="hub-section-number">1.4 </span>Optional depth and references <a class="header-anchor" href="#optional-depth-and-references" aria-label="Permalink to “1.4 Optional depth and references”">​</a></h3><table tabindex="0"><thead><tr><th>Chapter</th><th>What it explains</th></tr></thead><tbody><tr><td><a href="./ai-services.html">AWS AI services</a></td><td>Bedrock, SageMaker and Q Developer; application integration and boundaries</td></tr><tr><td><a href="./coverage-and-sources.html">Coverage, sources and certification</a></td><td>Course mapping, expected proficiency, source corrections and exam preparation</td></tr></tbody></table><p>Read networking and compute before RDS if private networking is new to you. Infrastructure as code comes early because both courses reuse it across services. AWS AI services are a continuation for applications that need model integration.</p><h2 id="one-application-several-responsibilities" tabindex="-1"><span class="hub-section-number">2 </span>One application, several responsibilities <a class="header-anchor" href="#one-application-several-responsibilities" aria-label="Permalink to “2 One application, several responsibilities”">​</a></h2><p>A small store provides a consistent example throughout the notes. Its frontend displays products, an API handles requests, databases preserve state, and an asynchronous import path processes uploaded files. Diagrams explain responsibilities; they are not deployment instructions or homework.</p>',15)),o(a,{"encoded-source":"flowchart%20LR%0A%20%20%20%20Browser%5BBrowser%5D%20--%3E%20CDN%5BCloudFront%5D%0A%20%20%20%20CDN%20--%3E%20Assets%5BPrivate%20S3%20assets%5D%0A%20%20%20%20Browser%20--%3E%20API%5BAPI%20Gateway%5D%0A%20%20%20%20Login%5BCognito%20user%20pool%5D%20--%3E%20API%0A%20%20%20%20API%20--%3E%20Functions%5BLambda%20handlers%5D%0A%20%20%20%20Functions%20--%3E%20Products%5BDynamoDB%20products%5D%0A%20%20%20%20Functions%20--%3E%20Orders%5BRDS%20orders%5D%0A%20%20%20%20Browser%20--%3E%20Upload%5BS3%20upload%5D%0A%20%20%20%20Upload%20--%3E%20Parser%5BImport%20parser%5D%0A%20%20%20%20Parser%20--%3E%20Queue%5BSQS%5D%0A%20%20%20%20Queue%20--%3E%20Worker%5BImport%20worker%5D%0A%20%20%20%20Worker%20--%3E%20Products%0A%20%20%20%20Worker%20--%3E%20Topic%5BSNS%20notifications%5D"}),e[1]||(e[1]=t('<h2 id="what-level-this-path-supports" tabindex="-1"><span class="hub-section-number">3 </span>What level this path supports <a class="header-anchor" href="#what-level-this-path-supports" aria-label="Permalink to “3 What level this path supports”">​</a></h2><p>Understanding the material and independently implementing its patterns can support <strong>strong junior AWS application-development proficiency</strong> for an existing JavaScript developer. Intermediate knowledge in individual services is possible. Medior proficiency also requires independent design decisions, unfamiliar troubleshooting, safe releases and operational ownership; reading a broad syllabus alone does not demonstrate those abilities.</p><p>Course completion and certification are separate outcomes. Use the official exam guide to identify exam-specific gaps. <a href="./../practice/aws/">AWS homework</a> now supplies the required Practitioner and Associate tracks, including every original optional/bonus task. Repeating work is marked; newly proposed gap exercises remain optional.</p><h2 id="connections-to-the-rest-of-the-hub" tabindex="-1"><span class="hub-section-number">4 </span>Connections to the rest of the hub <a class="header-anchor" href="#connections-to-the-rest-of-the-hub" aria-label="Permalink to “4 Connections to the rest of the hub”">​</a></h2><p><a href="./../node-js/">Node.js</a> explains the runtime, HTTP and database code that executes on AWS. <a href="./../node-js/module-12-resilient-distributed-systems.html">Resilient distributed systems</a> goes deeper into failure and recovery patterns. <a href="./../engineering/security.html">Engineering security</a> and <a href="./../engineering/delivery.html">delivery</a> supply cross-platform context. AWS adds service configuration, permissions, networking and managed infrastructure to those foundations.</p>',5))])}const g=n(d,[["render",l]]);export{b as __pageData,g as default};
